  contents: Content[]
  role?: Role
  author_name?: string
  response_id?: string
  message_id?: string
  conversation_id?: string
  model_id?: string
  created_at?: CreatedAtT
  finish_reason?: FinishReason
  additional_properties?: Record<string, unknown>
