  // Deployment methods
  async *streamDeployment(config: {
    entity_id: string
    agent_id: string
    resource_group: string
    app_name: string
    region?: string
    ui_mode?: string
  }): AsyncGenerator<{
    type: string
    message: string
    url?: string
    auth_token?: string
  }> {
    const response = await fetch(`${this.baseUrl}/v1/deployments`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ ...config, stream: true }),
    })

    if (!response.ok) {
      throw new Error(`Deployment failed: ${response.statusText}`)
    }

    const reader = response.body?.getReader()
    if (!reader) throw new Error('No response body')

    const decoder = new TextDecoder()
    let buffer = ''

    try {
      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        buffer += decoder.decode(value, { stream: true })
        const lines = buffer.split('\n')
        buffer = lines.pop() || ''

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6)
            if (data === '[DONE]') return
            try {
              yield JSON.parse(data)
            } catch (e) {
              // Emit error event for parsing failures
              yield {
                type: 'deploy.error',
                message: `Failed to parse deployment event: ${e instanceof Error ? e.message : 'Unknown error'}`,
              }
            }
          }
        }
      }
    } catch (error) {
      // Emit error event before throwing
      yield {
        type: 'deploy.failed',
        message: `Stream interrupted: ${error instanceof Error ? error.message : 'Unknown error'}`,
      }
      throw error
    } finally {
      reader.releaseLock()
    }
  }

  // ============================================================================
  // Workflow Session Management (uses /conversations API)
  // ============================================================================

  async listWorkflowSessions(entityId: string): Promise<{ data: WorkflowSession[] }> {
    entityId = encodeURIComponent(entityId)
    // Workflow sessions are conversations with entity_id and type metadata
    const url = `/v1/conversations?entity_id=${entityId}&type=workflow_session&agent_id=${entityId}`
    const response = await this.request<{
      object: 'list'
      data: ConversationApiResponse[]
      has_more: boolean
    }>(url)

    // Transform conversations to WorkflowSession format
    const sessions = response.data.map((conv) => ({
      conversation_id: conv.id,
      entity_id: (conv.metadata?.['entity_id'] as string) || entityId,
      agent_id: (conv.metadata?.['entity_id'] as string) || entityId,
      created_at: conv.created_at,
      metadata: {
        name:
          (conv.metadata?.['name'] as string) ||
          `Session ${new Date(conv.created_at * 1000).toLocaleString()}`,
        description: conv.metadata?.['description'] as string | undefined,
        type: 'workflow_session' as const,
        checkpoint_summary: conv.metadata?.['checkpoint_summary'] as
          | {
              count: number
              latest_iteration: number
              has_pending_hil: boolean
              pending_hil_count: number
            }
          | undefined,
      },
    }))

    return { data: sessions }
  }

  async createWorkflowSession(
    entityId: string,
    params?: { name?: string; description?: string },
  ): Promise<WorkflowSession> {
    // Create conversation with workflow session metadata
    const metadata = {
      entity_id: entityId,
      agent_id: entityId,
      type: 'workflow_session' as const,
      name: params?.name || `Session ${new Date().toLocaleString()}`,
      ...(params?.description && { description: params.description }),
    }

    const conversation = await this.createConversation(metadata)

    return {
      conversation_id: conversation.id,
      entity_id: entityId,
      agent_id: entityId,
      created_at: conversation.created_at,
      metadata: {
        name: metadata.name,
        description: metadata.description,
        type: 'workflow_session' as const,
      },
    }
  }

  async deleteWorkflowSession(_entityId: string, conversationId: string): Promise<void> {
    // Delete conversation (this also deletes all associated items/checkpoints)
    const success = await this.deleteConversation(conversationId)
    if (!success) {
      throw new Error('Failed to delete workflow session')
    }
  }
}

