// Span event structure (from OpenTelemetry)
export interface SpanEvent {
  name: string
  timestamp: number
  attributes: Record<string, unknown>
}

// Trace span for streaming
export interface TraceSpan {
  span_id: string
  parent_span_id?: string
  operation_name: string
  start_time: number
  end_time?: number
  duration_ms?: number
  attributes: Record<string, unknown>
  events: SpanEvent[]
  status: string
  raw_span?: Record<string, unknown>
}

// Helper type guards for Agent Framework content types
export function isTextContent(content: Content): content is TextContent {
  return content.type === 'text'
}

export function isFunctionCallContent(content: Content): content is FunctionCallContent {
  return content.type === 'function_call'
}

export function isFunctionResultContent(content: Content): content is FunctionResultContent {
  return content.type === 'function_result'
}

import { AttachmentItem } from '@shared/ui/types'
import type {
  AgentInfo,
