      <app-scroll-area class="flex-1 overflow-y-auto p-3 space-y-2">
        @if (executorRuns().length === 0) {
          <div class="text-center text-muted-foreground text-sm py-8">
            {{ isStreaming() ? 'Workflow is running...' : 'Ready to run workflow' }}
