        } @else {
          @for (run of executorRuns(); track run.itemId + $index) {
            <app-executor-run-item
              [run]="run"
              [isExpanded]="expandedRuns().has(run.executorId + '-' + run.runNumber)"
              [isSelected]="selectedExecutorId() === run.executorId"
