              <ng-icon name="lucideCheckCircle" class="w-4 h-4 text-green-500" />
              <span class="font-medium text-sm">Workflow Complete</span>
            </div>
            <div class="space-y-1">
              <div class="text-xs font-medium text-muted-foreground">Final Output:</div>
