/**
 * Helper function to safely access workflow dump as a typed Workflow
 */
export function getTypedWorkflow(workflowDump: WorkflowDump): Workflow | null {
  if (isWorkflow(workflowDump)) {
    return workflowDump
  }
  return null
}

