export class DebugPanelComponent {
  // --- Signal Inputs ---
  events = input.required<any[]>()
  isStreaming = input(false)
  canMinimize = input(false)

  // --- Signal Outputs ---
  onMinimize = output<void>()

  // --- Store & Logic ---
  private store = inject(DevUIStore)

  activeTab = computed(() => this.store.debugPanelTab)

  setActiveTab(v: 'events' | 'traces' | 'tools') {
    this.store.setDebugPanelTab(v)
  }

  // --- Computed (Replacement for useMemo) ---
  counts = computed(() => {
    const rawEvents = this.events()
    const processedEvents = processEventsForDisplay(rawEvents)

    const eventsCount = processedEvents.length
    const tracesCount = rawEvents.filter((e) => e.type === 'response.trace.completed').length
    const toolsCount =
      processedEvents.filter((e) => e.type === 'response.function_call.complete').length +
      rawEvents.filter((e) => getFunctionResultFromEvent(e) !== null).length

    return { eventsCount, tracesCount, toolsCount }
  })
}

export type ResponseErrorCode =
  | 'server_error'
  | 'rate_limit_exceeded'
  | 'invalid_prompt'
  | 'vector_store_timeout'
  | 'invalid_image'
  | 'invalid_image_format'
  | 'invalid_base64_image'
  | 'invalid_image_url'
  | 'image_too_large'
  | 'image_too_small'
  | 'image_parse_error'
  | 'image_content_policy_violation'
  | 'invalid_image_mode'
  | 'image_file_too_large'
  | 'unsupported_image_media_type'
  | 'empty_image_file'
  | 'failed_to_download_image'
  | 'image_file_not_found'

export interface ResponseError {
  code: ResponseErrorCode
  message: string
}

// OpenAI Response Usage (from response_usage.py)
export interface ResponseUsage {
  input_tokens: number
  output_tokens: number
  total_tokens: number
  input_tokens_details?: {
    cached_tokens: number
  }
  output_tokens_details?: {
    reasoning_tokens: number
  }
}

// Core OpenAI Response Stream Event
export interface ResponseStreamEvent {
  type: string
  item_id?: string
  output_index?: number
  content_index?: number
  sequence_number?: number

  // Different event types
  delta?: string // For text delta events
  logprobs?: Record<string, unknown>[]

  // Meta info
  id?: string
  object?: string
  created_at?: number
}

// Standard OpenAI Response Lifecycle Events
export interface ResponseCreatedEvent {
  type: 'response.created'
  response: {
    id: string
    status: 'in_progress'
    created_at: number
    output?: ResponseOutputItem[]
  }
  sequence_number?: number
}

export interface ResponseInProgressEvent {
  type: 'response.in_progress'
  response: {
    id: string
    status: 'in_progress'
  }
  sequence_number?: number
}

export interface ResponseCompletedEvent {
  type: 'response.completed'
  response: {
    id: string
    status?: 'completed'
    usage?: ResponseUsage // Optional usage information
    model?: string // Optional model information
    output?: ResponseOutputItem[] // Output items
    error?: ResponseError // Error if failed
    metadata?: Record<string, unknown> // Additional metadata
  }
  sequence_number?: number
}

export interface ResponseFailedEvent {
  type: 'response.failed'
  response: {
    id: string
    status: 'failed'
    error?: ResponseError
  }
  sequence_number?: number
}

// Custom Agent Framework OpenAI event types with structured data
export interface ResponseWorkflowEventComplete {
  type: 'response.workflow_event.completed'
  data: {
    event_type: string
    data?: Record<string, unknown>
    executor_id?: string
    timestamp: string
  }
  executor_id?: string
  item_id: string
  output_index: number
  sequence_number: number
}

// Function call event types - matching actual backend output
export interface ResponseFunctionCallComplete {
  type: 'response.function_call.complete'
  data: {
    name: string
    arguments: string | object
    call_id: string
  }
  item_id?: string
  output_index?: number
  sequence_number?: number
}

export interface ResponseFunctionCallDelta {
  type: 'response.function_call.delta'
  data: {
    name?: string
    call_id?: string
  }
  item_id?: string
  output_index?: number
  sequence_number?: number
}

export interface ResponseFunctionCallArgumentsDelta {
  type: 'response.function_call_arguments.delta'
  delta: string
  data?: {
    call_id?: string
    arguments?: string
  }
  item_id?: string
  output_index?: number
  sequence_number?: number
}

// OpenAI Responses API - Function Tool Call Item
export interface ResponseFunctionToolCall {
  id: string // Item ID
  call_id: string // Call ID for pairing with results
  name: string // Function name
  arguments: string // JSON arguments
  type: 'function_call'
  status?: 'in_progress' | 'completed' | 'incomplete'
}

// DevUI Extension: Output item types for response.output_item.added events
export interface ResponseOutputImageItem {
  id: string
  type: 'output_image'
  image_url: string
  alt_text?: string
  mime_type: string
}

export interface ResponseOutputFileItem {
  id: string
  type: 'output_file'
  filename: string
  file_url?: string
  file_data?: string
  mime_type: string
}

export interface ResponseOutputDataItem {
  id: string
  type: 'output_data'
  data: string
  mime_type: string
  description?: string
}

// Workflow Item Types - flexible interface for any workflow item
export interface WorkflowItem {
  type: string // "executor_action", "workflow_action", "message", or any future type
  id: string
  status?: 'in_progress' | 'completed' | 'failed' | 'cancelled'
  [key: string]: unknown // Allow any additional fields with unknown type
}

// Executor Action Item (DevUI specific)
export interface ExecutorActionItem extends WorkflowItem {
  type: 'executor_action'
  executor_id: string
  metadata?: Record<string, unknown>
  result?: unknown
  error?: unknown
}

// Type guard for executor actions
export function isExecutorAction(item: WorkflowItem): item is ExecutorActionItem {
  return item.type === 'executor_action' && 'executor_id' in item
}

// Union of all possible output items
export type ResponseOutputItem =
  | ResponseFunctionToolCall
  | ResponseOutputImageItem
  | ResponseOutputFileItem
  | ResponseOutputDataItem
