  type: 'file_path'
  file_id: string
  index: number
}

export type OutputTextAnnotation =
  | AnnotationFileCitation
  | AnnotationURLCitation
  | AnnotationContainerFileCitation
  | AnnotationFilePath

// Logprob types for output text
export interface LogprobTopLogprob {
  token: string
  bytes: number[]
  logprob: number
}

export interface Logprob {
  token: string
  bytes: number[]
