    this.patch({
      agents: s.agents.map((a: any) => (a.id === updatedAgent.id ? updatedAgent : a)),
      selectedAgent:
        s.selectedAgent?.id === updatedAgent.id && s.selectedAgent?.type === 'agent'
          ? updatedAgent
          : s.selectedAgent,
    })
