    this.patch({
      agents: s.agents.filter((a: any) => a.id !== entityId),
      workflows: s.workflows.filter((w: any) => w.id !== entityId),
      selectedAgent: s.selectedAgent?.id === entityId ? undefined : s.selectedAgent,
    })
