import { Directive, input, computed } from '@angular/core'
import { BadgeVariantProps, badgeVariants } from '../utils/badge.variants'
import { cn } from '../utils/utils'

@Directive({
  selector: '[appBadge]',
  standalone: true,
  host: {
    '[class]': 'computedClasses()',
  },
})
export class BadgeDirective {
  variant = input<BadgeVariantProps['variant']>('default')
  readonly userClass = input<string>('', { alias: 'class' })

  readonly computedClasses = computed(() =>
    cn(badgeVariants({ variant: this.variant() }), this.userClass()),
  )
}

import { Directive, input, computed, ElementRef, Renderer2, effect, untracked } from '@angular/core'
import { ButtonVariantProps, buttonVariants } from '../utils/button.variants'
import { cn } from '../utils/utils'

@Directive({
  selector: '[appButton]',
  standalone: true,
  host: {
    '[class]': 'hostClasses()',
    '[attr.disabled]': 'loading() || null',
  },
})
export class ButtonDirective {
  // The reason I didn't use `alias` was to observe the results across all four syntax variations.
  // This approach applies only to the Button Component and Directive; for all other components, `alias` should be used.
