              No tool executions yet. Tool calls will appear here during conversations.
            </div>
          } @else {
            <div class="space-y-3">
              @for (event of reversedToolEvents(); track $index) {
                @if (isSeparator(event)) {
                  <app-message-separator />
                } @else {
                  <app-tool-event-item [event]="event" />
