        @for (item of items(); track item.label) {
          <div class="flex items-center gap-2 text-xs">
            <div [ngClass]="['w-2', 'h-2', 'rounded-sm', item.color]"></div>

            <span class="text-muted-foreground w-20">{{ item.label }}</span>

