import { Component, signal } from '@angular/core'
import { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router'
import { CommonModule } from '@angular/common'

@Component({
  selector: 'app-testing',
  standalone: true,
  imports: [CommonModule, RouterOutlet, RouterLink, RouterLinkActive],
  template: `
    <div class="testing-container">
      <aside class="sidebar">
        <h2 class="sidebar-title">Components</h2>
        <nav class="nav-list">
          @for (item of components(); track item.path) {
            <a [routerLink]="[item.path]" routerLinkActive="active-link" class="nav-item">
              {{ item.name }}
            </a>
          }
        </nav>
      </aside>

      <main class="content-area">
        <div class="flex flex-col gap-4 p-4 bg-surface shadow-sm rounded-xl border border-gray-100">
          <router-outlet></router-outlet>
        </div>
      </main>
    </div>
  `,
  styles: [
    `
      .testing-container {
        display: flex;
        height: 100%;
        background: #f5f5f5;
      }
      .sidebar {
        width: 240px;
        border-right: 1px solid #ddd;
        background: #fff;
        padding: 1rem;
        display: flex;
        flex-direction: column;
      }
      .sidebar-title {
        font-size: 1.2rem;
        margin-bottom: 1rem;
        color: #333;
      }
      .nav-list {
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
      }
      .nav-item {
        padding: 0.75rem 1rem;
