        <span class="text-sm font-medium text-green-800 dark:text-green-300">Function Result</span>
        <ng-icon
          [name]="isExpanded() ? 'lucideChevronDown' : 'lucideChevronRight'"
          class="h-4 w-4 text-green-600 dark:text-green-400 ml-auto"
        />
      </div>
      @if (isExpanded()) {
