          </button>

          <button tabsTrigger value="tools" class="flex-1 gap-1.5">
            Tools
            @if (counts().toolsCount > 0) {
              <span
                class="text-[10px] bg-muted-foreground/20 text-muted-foreground px-1.5 py-0.5 rounded-full min-w-5 text-center"
              >
                {{ counts().toolsCount }}
