computed(() => {
    const dump = this.workflowDump()
    if (!dump) return { initialNodes: [], initialEdges: [] }

    const nodes = convertWorkflowDumpToNodes(
      dump,
      (id: string, data: any) => this.onNodeSelect.emit({ id, data }),
